# Document scanner + OCR tools
SPRIV="<p class='priv'>🔒 Your documents never leave your device. Edge detection, cropping, filters, PDF creation and text recognition all run inside your browser—nothing is uploaded.</p>"
ui=r"""<div class='scanbar'><label class='btn cam'>📷 Take photo<input id='cam' type='file' accept='image/*' capture='environment' hidden></label></div>
<label class='drop' id='drop'><input id='up' type='file' accept='image/*,.heic,.heif' multiple hidden><b>Upload document photos</b><span>JPG, PNG, WEBP or HEIC · or drag &amp; drop · add as many pages as you like</span></label>
<div id='ed' hidden><div class='edhead'><b id='edt'>Page 1</b><span class='muted' id='edinfo'></span></div><div class='prevwrap'><canvas id='pc'></canvas></div>
<div class='edctl'><select id='flt' aria-label='Filter'><option value='enhance'>Magic color</option><option value='bw'>B&amp;W scan</option><option value='gray'>Grayscale</option><option value='original'>Original</option></select><button type='button' class='btn sm ghost' id='rl' aria-label='Rotate left'>⟲</button><button type='button' class='btn sm ghost' id='rr' aria-label='Rotate right'>⟳</button><button type='button' class='btn sm ghost' id='adjb'>Adjust corners</button><button type='button' class='btn sm danger' id='del'>Delete</button></div>
<div id='adj' hidden><p class='muted'>Drag the green corners onto the corners of the paper.</p><div class='edwrap'><canvas id='ec'></canvas></div><div class='edctl'><button type='button' class='btn sm ghost' id='auto'>Auto-detect</button><button type='button' class='btn sm ghost' id='full'>Whole image</button><button type='button' class='btn sm' id='done'>Apply</button></div></div></div>
<div id='pgs' class='pages'></div>
<div class='opts' id='exp' hidden><div><label for='ps'>PDF page size</label><select id='ps'><option value='letter'>US Letter</option><option value='a4'>A4</option><option value='fit'>Fit to scan</option></select></div><div><label class='chk' style='margin-top:38px'><input id='srch' type='checkbox'> Searchable PDF (OCR text layer)</label></div></div>
<div class='btnrow' id='expb' hidden><button type='button' class='btn' id='pdf'>Download PDF</button><button type='button' class='btn ghost' id='jpg'>Download JPG</button><button type='button' class='btn ghost' id='ocr'>Extract text (OCR)</button></div>
<p id='status' class='status'></p><div id='out'></div><div id='txtw' hidden><label for='txt'>Recognized text</label><textarea id='txt' rows='10'></textarea><button type='button' class='btn sm' id='cpt'>Copy text</button></div>"""+SPRIV
js=r"""var APP=window.APP={pages:[],cur:-1};var ec=UI.$('#ec'),ctx=ec.getContext('2d'),drag=-1,scale=1;
async function addFiles(fs){for(var i=0;i<fs.length;i++){UI.status('Reading '+fs[i].name+'…');try{var img=await UI.decode(fs[i]),m=Math.min(1,3000/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*m);c.height=Math.round(img.naturalHeight*m);c.getContext('2d').drawImage(img,0,0,c.width,c.height);
 var q=Scan.detect(c),pg={src:c,quad:q||Scan.fullQuad(c.width,c.height,0),auto:!!q,filter:'enhance',rot:0,skew:0,name:fs[i].name};autofix(pg,true);APP.pages.push(pg);render(pg)}catch(e){UI.status(e.message,1);continue}}
 draw();if(APP.pages.length){var L=APP.pages[APP.pages.length-1];edit(APP.pages.length-1);UI.status(APP.pages.length+' page(s). '+(L.auto?'Page detected and straightened automatically.':'Page edges not found—straightened the whole photo. Tap “Adjust corners” to crop.'),!L.auto&&false)}}
function autofix(pg,orient){var w=Scan.warp(pg.src,pg.quad,1400);pg.skew=Scan.skew(w);if(orient){pg.rot=Scan.orient(Scan.rotateFine(w,pg.skew,pg.auto&&Math.abs(pg.skew)<4))}}
function render(pg){pg.out=Scan.rotate(Scan.filter(Scan.rotateFine(Scan.warp(pg.src,pg.quad,2200),pg.skew,pg.auto&&Math.abs(pg.skew)<4),pg.filter),pg.rot);var t=document.createElement('canvas'),k=160/Math.max(pg.out.width,pg.out.height);t.width=Math.round(pg.out.width*k);t.height=Math.round(pg.out.height*k);t.getContext('2d').drawImage(pg.out,0,0,t.width,t.height);pg.thumb=t.toDataURL('image/jpeg',0.8)}
function draw(){var g=UI.$('#pgs');g.innerHTML='';APP.pages.forEach(function(p,i){var d=document.createElement('div');d.className='pg'+(i===APP.cur?' on':'');d.innerHTML='<img alt=""><span>'+(i+1)+'</span><div><button type="button" aria-label="Move left">←</button><button type="button" aria-label="Move right">→</button></div>';d.querySelector('img').src=p.thumb;
 d.querySelector('img').onclick=function(){edit(i)};var b=d.querySelectorAll('button');b[0].onclick=function(){if(i){APP.pages.splice(i-1,0,APP.pages.splice(i,1)[0]);if(APP.cur===i)APP.cur--;draw()}};b[1].onclick=function(){if(i<APP.pages.length-1){APP.pages.splice(i+1,0,APP.pages.splice(i,1)[0]);if(APP.cur===i)APP.cur++;draw()}};g.appendChild(d)});
 var has=APP.pages.length>0;UI.$('#exp').hidden=UI.$('#expb').hidden=!has;if(!has)UI.$('#ed').hidden=true}
function edit(i){APP.cur=i;var p=APP.pages[i];UI.$('#ed').hidden=false;UI.$('#adj').hidden=true;UI.$('#edt').textContent='Page '+(i+1)+' of '+APP.pages.length;UI.$('#edinfo').textContent=(p.auto?'Auto-cropped':'Whole photo')+(Math.abs(p.skew)>=0.1?' · straightened '+Math.abs(p.skew).toFixed(1)+'°':'')+(p.rot?' · rotated '+p.rot*90+'°':'');UI.$('#flt').value=p.filter;preview();draw()}
function openAdj(){var p=APP.pages[APP.cur];UI.$('#adj').hidden=false;var maxW=UI.$('.edwrap').clientWidth||600,maxH=Math.max(260,window.innerHeight*0.6);scale=Math.min(maxW/p.src.width,maxH/p.src.height,1);ec.width=Math.round(p.src.width*scale);ec.height=Math.round(p.src.height*scale);paint()}
function paint(){var p=APP.pages[APP.cur];if(!p)return;ctx.drawImage(p.src,0,0,ec.width,ec.height);var q=p.quad.map(function(v){return [v[0]*scale,v[1]*scale]});ctx.fillStyle='rgba(21,128,61,.18)';ctx.strokeStyle='#15803d';ctx.lineWidth=3;ctx.beginPath();q.forEach(function(v,k){k?ctx.lineTo(v[0],v[1]):ctx.moveTo(v[0],v[1])});ctx.closePath();ctx.fill();ctx.stroke();
 q.forEach(function(v,k){ctx.beginPath();ctx.arc(v[0],v[1],k===drag?16:12,0,7);ctx.fillStyle='#fff';ctx.fill();ctx.lineWidth=4;ctx.strokeStyle='#15803d';ctx.stroke()})}
function preview(){var p=APP.pages[APP.cur],pc=UI.$('#pc'),k=Math.min(1,(UI.$('.prevwrap').clientWidth||400)/p.out.width,420/p.out.height);pc.width=Math.round(p.out.width*k);pc.height=Math.round(p.out.height*k);pc.getContext('2d').drawImage(p.out,0,0,pc.width,pc.height)}
function pos(e){var r=ec.getBoundingClientRect();return [(e.clientX-r.left)*ec.width/r.width,(e.clientY-r.top)*ec.height/r.height]}
ec.addEventListener('pointerdown',function(e){var p=APP.pages[APP.cur];if(!p)return;var m=pos(e),best=-1,bd=40*ec.width/ec.getBoundingClientRect().width;p.quad.forEach(function(v,k){var d=Math.hypot(v[0]*scale-m[0],v[1]*scale-m[1]);if(d<bd){bd=d;best=k}});drag=best;if(best>=0){ec.setPointerCapture(e.pointerId);e.preventDefault()}paint()});
ec.addEventListener('pointermove',function(e){if(drag<0)return;var p=APP.pages[APP.cur],m=pos(e);p.quad[drag]=[Math.max(0,Math.min(p.src.width,m[0]/scale)),Math.max(0,Math.min(p.src.height,m[1]/scale))];paint()});
function up(){if(drag<0)return;drag=-1;var p=APP.pages[APP.cur];p.quad=Scan.order(p.quad);autofix(p,false);render(p);paint();preview();draw()}ec.addEventListener('pointerup',up);ec.addEventListener('pointercancel',up);
function upd(f){var p=APP.pages[APP.cur];if(!p)return;f(p);render(p);paint();preview();draw()}
UI.$('#auto').onclick=function(){upd(function(p){var q=Scan.detect(p.src);if(q){p.quad=q;p.auto=true;autofix(p,false)}UI.status(q?'Edges detected.':'Could not find clear document edges—adjust the corners by hand.',!q)})};
UI.$('#full').onclick=function(){upd(function(p){p.quad=Scan.fullQuad(p.src.width,p.src.height,0);autofix(p,false)})};UI.$('#adjb').onclick=function(){openAdj();UI.$('#adj').scrollIntoView({block:'nearest'})};UI.$('#rl').onclick=function(){upd(function(p){p.rot=(p.rot+3)%4})};UI.$('#rr').onclick=function(){upd(function(p){p.rot=(p.rot+1)%4})};
UI.$('#flt').onchange=function(){var v=this.value;upd(function(p){p.filter=v})};UI.$('#done').onclick=function(){UI.$('#adj').hidden=true;edit(APP.cur)};
UI.$('#del').onclick=function(){APP.pages.splice(APP.cur,1);APP.cur=-1;UI.$('#ed').hidden=true;draw();if(APP.pages.length)edit(Math.min(APP.pages.length-1,0))};
UI.drop(UI.$('#drop'),{multiple:true,onFiles:addFiles});UI.$('#cam').addEventListener('change',function(){var f=[].slice.call(this.files);this.value='';addFiles(f)});
function jpeg(cv,q){return new Promise(function(ok){cv.toBlob(ok,'image/jpeg',q||0.88)})}
function prog(i,n,what){return function(m){if(m.status==='recognizing text')UI.status(what+' page '+(i+1)+' / '+n+': '+Math.round(m.progress*100)+'%');else UI.status('Loading text recognition… '+Math.round((m.progress||0)*100)+'%')}}
UI.$('#pdf').onclick=async function(){try{var doc=await PDFLib.PDFDocument.create(),font=await doc.embedFont(PDFLib.StandardFonts.Helvetica),S={letter:[612,792],a4:[595.28,841.89]},ps=UI.$('#ps').value,ocr=UI.$('#srch').checked,n=APP.pages.length;
 for(var i=0;i<n;i++){var p=APP.pages[i];UI.status('Building page '+(i+1)+' of '+n+'…');var im=await doc.embedJpg(await (await jpeg(p.out)).arrayBuffer()),iw=p.out.width*72/200,ih=p.out.height*72/200,pw,ph;
  if(ps==='fit'){pw=iw;ph=ih}else{pw=S[ps][0];ph=S[ps][1];if(iw>ih){var t=pw;pw=ph;ph=t}}var r=Math.min(pw/iw,ph/ih),w=iw*r,h=ih*r,x0=(pw-w)/2,y0=(ph-h)/2,pg=doc.addPage([pw,ph]);pg.drawImage(im,{x:x0,y:y0,width:w,height:h});
  if(ocr){var d=await Scan.ocr(p.out,prog(i,n,'Recognizing text on')),k=w/p.out.width;(d.words||[]).forEach(function(wd){var tx=wd.text.replace(/[^\x20-\x7E]/g,'');if(!tx.trim())return;var b=wd.bbox,bw=(b.x1-b.x0)*k,bh=(b.y1-b.y0)*k,sz=Math.max(1,Math.min(bh*1.1,bw/Math.max(0.01,font.widthOfTextAtSize(tx,1))));
   try{pg.drawText(tx,{x:x0+b.x0*k,y:y0+h-b.y1*k+bh*0.15,size:sz,font:font,opacity:0})}catch(e){}})}}
 var bytes=await doc.save();UI.results([{name:'scan.pdf',blob:new Blob([bytes],{type:'application/pdf'}),note:n+' page(s)'+(ocr?' · searchable':'')}]);UI.status('PDF ready.')}catch(e){UI.status(e.message,1)}};
UI.$('#jpg').onclick=async function(){var out=[];for(var i=0;i<APP.pages.length;i++){var p=APP.pages[i];out.push({name:'scan_page'+(i+1)+'.jpg',blob:await jpeg(p.out,0.9),note:p.out.width+'×'+p.out.height})}UI.results(out);UI.status('JPG ready.')};
UI.$('#ocr').onclick=async function(){try{var all=[],n=APP.pages.length;for(var i=0;i<n;i++){var d=await Scan.ocr(APP.pages[i].out,prog(i,n,'Reading'));all.push(d.text.trim())}UI.$('#txt').value=all.join('\n\n— page break —\n\n');UI.$('#txtw').hidden=false;UI.status('Text extracted from '+n+' page(s).')}catch(e){UI.status('Text recognition failed: '+e.message,1)}};
UI.$('#cpt').onclick=function(){UI.copy(UI.$('#txt').value,this)};"""
add("document-scanner","PDF tools","Document Scanner","Online Document Scanner – Scan to PDF Free, No Upload (Works on Phone)","Free online document scanner: take a photo with your phone, auto-detect the page edges, crop, clean up to a crisp scan and save as PDF or JPG. Runs in your browser; nothing is uploaded.",ui,js,
"<h2>How to scan a document with your phone</h2><ol><li>Open this page on your phone and tap <b>Take photo</b>. Place the page on a darker, plain surface and fill most of the frame—contrast helps the edge detection.</li><li>The page is found, cropped and straightened automatically—even when the photo was taken at an angle or the page is rotated. Text lines are leveled and sideways or upside-down pages are turned upright. If the crop isn't perfect, tap <b>Adjust corners</b>.</li><li>Choose a filter. <b>Magic color</b> evens out shadows and whitens the paper while keeping colors (good for forms with stamps or signatures). <b>B&amp;W scan</b> gives a crisp black-and-white look like an office scanner—ideal for text. <b>Grayscale</b> is in between.</li><li>Add more pages, reorder them with the arrows, then tap <b>Download PDF</b>.</li></ol><h2>Scan to PDF that's searchable</h2><p>Tick <b>Searchable PDF</b> and the scanner runs text recognition (OCR) on every page, then adds an invisible text layer. You can then search the PDF with Ctrl+F, select and copy text, and document systems can index it—just like a PDF from a professional scanner.</p><h2>Why a browser scanner instead of an app?</h2><p>Scanner apps often require an account, add watermarks, push subscriptions and upload your documents to their cloud. Here, the camera image is processed on your own phone or computer: edge detection, perspective correction and OCR all run locally. That makes it suitable for IDs, contracts, payslips and medical forms.</p><h2>Tips for a clean scan</h2><ul><li>Use daylight or an even light source; avoid your own shadow over the page.</li><li>Hold the phone parallel to the page. The perspective correction fixes moderate angles, but very steep angles lose sharpness.</li><li>For receipts, use B&amp;W scan; for photos and color charts, use Original.</li></ul>"
+FAQ(("Is it really free and without a watermark?","Yes. No sign-up, no watermark and no page limit."),("Does it work on iPhone and Android?","Yes, in Safari, Chrome, Firefox and Edge. The Take photo button opens the rear camera; HEIC photos from iPhones are supported."),("Are my scans uploaded or stored?","No. Everything happens in your browser. The text-recognition engine (Tesseract) is downloaded once and then runs on your device."),("What languages does OCR support?","The language of this page: English, Vietnamese, Spanish, Portuguese, French, German, Italian, Indonesian or Japanese, including accents and diacritics.")),libs=("pdf-lib.min.js","scan.js"))
ui2=r"""<label class='drop' id='drop'><input type='file' accept='image/*,.heic,.heif' multiple hidden><b>Choose images</b><span>Screenshots, photos or scans · drag &amp; drop · or paste with Ctrl+V</span></label>
<div class='opts'><label for='ol'>Language of the text</label> <select id='ol'><option value='eng'>English</option><option value='vie'>Tiếng Việt</option><option value='vie+eng'>Tiếng Việt + English</option><option value='spa'>Español</option><option value='por'>Português</option><option value='fra'>Français</option><option value='deu'>Deutsch</option><option value='ita'>Italiano</option><option value='ind'>Bahasa Indonesia</option><option value='jpn'>日本語</option></select></div>
<div class='opts'><label class='chk'><input id='en' type='checkbox' checked> Clean up image before reading (recommended for photos)</label></div><p id='status' class='status'></p>
<div id='res' hidden><label for='txt'>Extracted text</label><textarea id='txt' rows='14'></textarea><div class='btnrow'><button type='button' class='btn sm' id='cp'>Copy text</button><button type='button' class='btn sm ghost' id='dl'>Download .txt</button></div><p class='muted' id='conf'></p></div>"""+"<p class='priv'>🔒 Your images never leave your device. Text recognition runs in your browser with the open-source Tesseract engine—nothing is uploaded.</p>"
js2=r"""async function go(fs){var all=[],cf=[];for(var i=0;i<fs.length;i++){try{var img=await UI.decode(fs[i]),c=document.createElement('canvas'),m=Math.min(1,3000/Math.max(img.naturalWidth,img.naturalHeight));c.width=Math.round(img.naturalWidth*m);c.height=Math.round(img.naturalHeight*m);c.getContext('2d').drawImage(img,0,0,c.width,c.height);
 if(UI.$('#en').checked)Scan.filter(c,'gray');var n=fs.length,k=i;var d=await Scan.ocr(c,function(p){UI.status(p.status==='recognizing text'?'Reading image '+(k+1)+' / '+n+': '+Math.round(p.progress*100)+'%':'Loading text recognition… '+Math.round((p.progress||0)*100)+'%')},UI.$('#ol').value);all.push((fs.length>1?'— '+fs[i].name+' —\n':'')+d.text.trim());cf.push(Math.round(d.confidence))}catch(e){UI.status(e.message,1)}}
 if(all.length){UI.$('#txt').value=all.join('\n\n');UI.$('#res').hidden=false;UI.$('#conf').textContent='Average confidence: '+cf.join('%, ')+'%. Check names and numbers before using the text.';UI.status('Done.')}}
UI.$('#ol').value=Scan.ocrDefault();UI.drop(UI.$('#drop'),{multiple:true,onFiles:go});document.addEventListener('paste',function(e){var f=[].slice.call(e.clipboardData.files||[]).filter(function(x){return /^image\//.test(x.type)});if(f.length)go(f.map(function(x,i){return new File([x],'pasted-'+(i+1)+'.png',{type:x.type})}))});
UI.$('#cp').onclick=function(){UI.copy(UI.$('#txt').value,this)};UI.$('#dl').onclick=function(){UI.download(new Blob([UI.$('#txt').value],{type:'text/plain'}),'extracted-text.txt')};"""
add("image-to-text","Text tools","Image to Text (OCR)","Image to Text Converter – Free OCR Online, No Upload","Extract text from images, screenshots and photos of documents with free OCR. Copy or download the text. Runs in your browser; your images are never uploaded.",ui2,js2,
"<h2>Copy text from any image</h2><p>Drop a screenshot, a photo of a page or a scanned image and the text is recognized in a few seconds. You can also copy an image and press <b>Ctrl+V</b> (Cmd+V on Mac) anywhere on the page. Edit the result in the box, then copy it or download it as a .txt file.</p><h2>How it works</h2><p>FileMoss uses Tesseract, the open-source OCR engine originally developed at HP and later maintained with Google's support, compiled to WebAssembly so it runs inside your browser. Choose the language of the text: English, Vietnamese, Spanish, Portuguese, French, German, Italian, Indonesian or Japanese. The matching language model (about 1–3 MB) is downloaded the first time and cached. Your image is processed locally and never sent to a server.</p><h2>Getting the best results</h2><ul><li>Use images where text is at least 20 pixels tall; zoom in before taking a screenshot of small text.</li><li>Keep the page flat and well lit. For skewed photos, run them through the <a href='/document-scanner/'>Document Scanner</a> first to crop and straighten them.</li><li>Printed text works best. Handwriting is usually not recognized reliably.</li></ul>"
+FAQ(("Is this OCR free?","Yes, unlimited and without sign-up."),("Can it read PDFs?","Convert the PDF pages to images with <a href='/pdf-to-jpg/'>PDF to JPG</a> first, then drop the images here."),("Which languages are supported?","English, Vietnamese, Spanish, Portuguese, French, German, Italian, Indonesian and Japanese, with full accents and diacritics. Pick the language of the text before you add the image; it defaults to the language of this page.")),libs=("scan.js",))
